// Host test of the version-2 protobuf decoder. Sample directory (optional): argv[1], written by
// the Java contract test (part 2); without it only the built-in samples run.
#include <assert.h>
#include <stdio.h>
#include <string.h>
#include <string>
#include "../usermods/kite_wind/proto_sample.h"
#include "../usermods/kite_wind/render_proto.h"

using namespace KiteWindProto;
using KiteWindProtoSample::Spec;

static int failures = 0;
#define CHECK(c) do { if (!(c)) { printf("FAIL %s:%d %s\n", __FILE__, __LINE__, #c); failures++; } } while (0)

static uint8_t buf[MAX_RESPONSE_BYTES + 1024];
static Frame frame;
static Definition def;

struct Source { const uint8_t* data; size_t length; size_t offset; size_t stopAt; };
static bool readSource(pb_istream_t* stream, pb_byte_t* out, size_t count) {
  Source* s = static_cast<Source*>(stream->state);
  if (s->offset + count > s->stopAt) return false;  // connection ended early
  memcpy(out, s->data + s->offset, count);
  s->offset += count;
  return true;
}

static Error decodeSpec(const Spec& spec) {
  size_t n = KiteWindProtoSample::build(spec, buf, sizeof(buf));
  assert(n > 0);
  return decodeBuffer(buf, n, frame, def);
}

static void maximalSampleDecodes() {
  Spec spec;
  size_t n = KiteWindProtoSample::build(spec, buf, sizeof(buf));
  CHECK(n > 0 && n <= MAX_RESPONSE_BYTES);
  CHECK(decodeBuffer(buf, n, frame, def) == Error::Ok);
  CHECK(frame.contractVersion == CONTRACT_VERSION);
  CHECK(frame.hasDefinition);
  CHECK(def.trackCount == 26 && def.segmentCount == 256 && frame.lampCount == 51);
  CHECK(def.tracks[0].curve == Curve::Constant && def.tracks[0].firstSegment == 0);
  CHECK(def.tracks[2].curve == Curve::Cosine && def.tracks[2].firstSegment == 2);
  uint32_t total = 0;
  for (uint8_t t = 0; t < def.trackCount; t++) total += def.tracks[t].segmentCount;
  CHECK(total == 256);
  CHECK(frame.lamps[50].pixel == 51 && frame.lamps[0].r == 255 && frame.lamps[0].b == 255);
  CHECK(frame.weather == Weather::Simulated && frame.brightness == 255);
  CHECK(frame.digest[0] == 0xA5);
  CHECK(validateLamps(frame, def) == Error::Ok);
  printf("maximal sample: %u bytes\n", static_cast<unsigned>(n));
}

static void streamEqualsBuffer() {
  Spec spec;
  size_t n = KiteWindProtoSample::build(spec, buf, sizeof(buf));
  Source src = {buf, n, 0, n};
  pb_istream_t in = streamFrom(readSource, &src, n);
  CHECK(decode(&in, frame, def) == Error::Ok);
  CHECK(src.offset == n && def.segmentCount == 256);
}

static void truncatedStreamFails() {
  Spec spec;
  size_t n = KiteWindProtoSample::build(spec, buf, sizeof(buf));
  for (size_t stop = 0; stop < n; stop += 37) {
    Source src = {buf, n, 0, stop};
    pb_istream_t in = streamFrom(readSource, &src, n);  // Content-Length promised n bytes
    CHECK(decode(&in, frame, def) != Error::Ok);
  }
}

static void limitsAndShapes() {
  Spec s;
  s = Spec(); s.contract = 1; CHECK(decodeSpec(s) == Error::UnsupportedVersion);
  s = Spec(); s.digestLength = 0; CHECK(decodeSpec(s) == Error::BadDigest);
  s = Spec(); s.digestLength = 31; CHECK(decodeSpec(s) == Error::Malformed);
  s = Spec(); s.tracks = 27; CHECK(decodeSpec(s) == Error::TooManyTracks);
  s = Spec(); s.segments = 257; CHECK(decodeSpec(s) == Error::TooManySegments);
  s = Spec(); s.lamps = 52; CHECK(decodeSpec(s) == Error::TooManyLamps);
  s = Spec(); s.duration = 0; CHECK(decodeSpec(s) == Error::OutOfRange);
  s = Spec(); s.duration = 60001; CHECK(decodeSpec(s) == Error::OutOfRange);
  s = Spec(); s.duration = 60000; CHECK(decodeSpec(s) == Error::Ok);
  s = Spec(); s.to = 101; CHECK(decodeSpec(s) == Error::OutOfRange);
  s = Spec(); s.curve = 3; CHECK(decodeSpec(s) == Error::BadCurve);
  s = Spec(); s.constantSegments = 2; CHECK(decodeSpec(s) == Error::BadTrackShape);
  s = Spec(); s.countSkew = 1; CHECK(decodeSpec(s) == Error::BadTrackShape);
  s = Spec(); s.countSkew = -1; CHECK(decodeSpec(s) == Error::BadTrackShape);
  s = Spec(); s.lamps = 1; s.firstPixel = 0; CHECK(decodeSpec(s) == Error::PixelOutOfRange);
  s = Spec(); s.lamps = 1; s.firstPixel = 52; CHECK(decodeSpec(s) == Error::PixelOutOfRange);
  s = Spec(); s.duplicatePixel = true; CHECK(decodeSpec(s) == Error::DuplicatePixel);
  s = Spec(); s.rgb = 0x1000000; CHECK(decodeSpec(s) == Error::OutOfRange);
  s = Spec(); s.weather = 3; CHECK(decodeSpec(s) == Error::OutOfRange);
  s = Spec(); s.brightness = 256; CHECK(decodeSpec(s) == Error::OutOfRange);
  s = Spec(); s.track = 26; CHECK(decodeSpec(s) == Error::BadTrackRef);
  s = Spec(); s.track = 25; CHECK(decodeSpec(s) == Error::Ok);
  Definition small = def;
  small.trackCount = 3;
  CHECK(validateLamps(frame, small) == Error::BadTrackRef);
  s = Spec(); s.definition = false; CHECK(decodeSpec(s) == Error::Ok);
  CHECK(!frame.hasDefinition && def.trackCount == 0);
  CHECK(decodeBuffer(buf, MAX_RESPONSE_BYTES + 1, frame, def) == Error::TooLarge);
}

static std::string dump(const Frame& f, const Definition& d) {
  std::string out;
  char line[128];
  snprintf(line, sizeof(line), "contract %u\n", static_cast<unsigned>(f.contractVersion));
  out += line;
  out += "digest ";
  for (size_t i = 0; i < DIGEST_BYTES; i++) { snprintf(line, sizeof(line), "%02x", f.digest[i]); out += line; }
  out += f.hasDefinition ? "\ndefinition yes\n" : "\ndefinition no\n";
  if (f.hasDefinition) {
    for (uint8_t t = 0; t < d.trackCount; t++) {
      snprintf(line, sizeof(line), "track %u %u %u %u\n", t, static_cast<unsigned>(d.tracks[t].curve),
               d.tracks[t].firstSegment, d.tracks[t].segmentCount);
      out += line;
    }
    for (uint16_t i = 0; i < d.segmentCount; i++) {
      snprintf(line, sizeof(line), "segment %u %u %u %u\n", i, d.segments[i].durationMs, d.segments[i].from, d.segments[i].to);
      out += line;
    }
  }
  for (uint8_t i = 0; i < f.lampCount; i++) {
    const Lamp& l = f.lamps[i];
    snprintf(line, sizeof(line), "lamp %u %u %02x%02x%02x\n", l.pixel, l.track, l.r, l.g, l.b);
    out += line;
  }
  snprintf(line, sizeof(line), "weather %u\nbrightness %u\n", static_cast<unsigned>(f.weather), f.brightness);
  out += line;
  return out;
}

static std::string readFile(const char* path, bool* ok) {
  FILE* f = fopen(path, "rb");
  *ok = f != nullptr;
  if (!f) return "";
  std::string s;
  char chunk[512];
  size_t n;
  while ((n = fread(chunk, 1, sizeof(chunk), f)) > 0) s.append(chunk, n);
  fclose(f);
  return s;
}

static void javaSamples(const char* dir) {
  if (!dir) return;
  const char* names[] = {"maximal", "dark", "no-definition"};
  for (const char* name : names) {
    char path[512];
    bool ok = false;
    snprintf(path, sizeof(path), "%s/%s.bin", dir, name);
    std::string bin = readFile(path, &ok);
    CHECK(ok);
    snprintf(path, sizeof(path), "%s/%s.txt", dir, name);
    std::string want = readFile(path, &ok);
    CHECK(ok);
    CHECK(decodeBuffer(reinterpret_cast<const uint8_t*>(bin.data()), bin.size(), frame, def) == Error::Ok);
    CHECK(dump(frame, def) == want);
    printf("%s: identical to the Java dump\n", name);
  }
}

int main(int argc, char** argv) {
  maximalSampleDecodes();
  streamEqualsBuffer();
  truncatedStreamFails();
  limitsAndShapes();
  javaSamples(argc > 1 ? argv[1] : nullptr);
  if (failures) { printf("%d failure(s)\n", failures); return 1; }
  printf("kite-wind-proto-test: all passed\n");
  return 0;
}
